// Имена/пропсы Jinx UI ниже опираются на публично задокументированную часть API
// (JxButton, JxSlider, JxSelect); остальное — разметка на токенах var(--jx-*).
import { useState } from 'react';
import { JxButton, JxSelect, JxSlider } from '@jinx-ui/react';

export type AppearanceSettings = {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  fontFamily: string;
};

type Props = {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
};

const THEMES: ReadonlyArray<{ value: AppearanceSettings['theme']; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

export default function AppearanceSettingsScreen({ defaultValue, onChange }: Props) {
  const [settings, setSettings] = useState<AppearanceSettings>({ ...DEFAULTS, ...defaultValue });

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel = THEMES.find((t) => t.value === settings.theme)?.label ?? '';

  return (
    <section
      className="jx-stack"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
        background: 'var(--jx-color-surface)',
        color: 'var(--jx-color-fg)',
        borderRadius: 'var(--jx-radius-lg)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-3)' }}>
        <h2 style={{ margin: 0, font: 'var(--jx-font-heading-md)' }}>Внешний вид</h2>
        <span
          style={{
            padding: 'var(--jx-space-1) var(--jx-space-3)',
            borderRadius: 'var(--jx-radius-full)',
            border: '1px solid var(--jx-color-border)',
            color: 'var(--jx-color-fg-muted)',
            font: 'var(--jx-font-body-sm)',
          }}
        >
          {themeLabel}
        </span>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <span id="jx-theme-label" style={{ font: 'var(--jx-font-body-sm)', color: 'var(--jx-color-fg-muted)' }}>
          Тема
        </span>
        <div
          role="group"
          aria-labelledby="jx-theme-label"
          style={{
            display: 'inline-flex',
            gap: 'var(--jx-space-1)',
            padding: 'var(--jx-space-1)',
            borderRadius: 'var(--jx-radius-md)',
            border: '1px solid var(--jx-color-border)',
            width: 'fit-content',
          }}
        >
          {THEMES.map((option) => (
            <JxButton
              key={option.value}
              variant={settings.theme === option.value ? 'primary' : 'ghost'}
              aria-pressed={settings.theme === option.value}
              onClick={() => update({ theme: option.value })}
            >
              {option.label}
            </JxButton>
          ))}
        </div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <label
          htmlFor="jx-scale"
          style={{ display: 'flex', justifyContent: 'space-between', font: 'var(--jx-font-body-sm)' }}
        >
          <span style={{ color: 'var(--jx-color-fg-muted)' }}>Масштаб интерфейса</span>
          <span aria-live="polite">{settings.scale}%</span>
        </label>
        <JxSlider
          id="jx-scale"
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value: number) => update({ scale: value })}
        />
      </div>

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-4)' }}>
        <span id="jx-dense-label" style={{ font: 'var(--jx-font-body-sm)' }}>
          Плотная вёрстка
        </span>
        <JxButton
          variant={settings.dense ? 'primary' : 'secondary'}
          role="switch"
          aria-checked={settings.dense}
          aria-labelledby="jx-dense-label"
          onClick={() => update({ dense: !settings.dense })}
        >
          {settings.dense ? 'Включена' : 'Выключена'}
        </JxButton>
      </div>

      <hr style={{ border: 0, borderTop: '1px solid var(--jx-color-border)', margin: 0 }} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
        <h3 style={{ margin: 0, font: 'var(--jx-font-heading-sm)' }}>Ещё</h3>
        <label htmlFor="jx-font" style={{ font: 'var(--jx-font-body-sm)', color: 'var(--jx-color-fg-muted)' }}>
          Шрифт
        </label>
        <JxSelect
          id="jx-font"
          value={settings.fontFamily}
          onValueChange={(value: string) => update({ fontFamily: value })}
          options={FONTS}
        />
      </div>
    </section>
  );
}

